{
  "flashcards": [
    {
      "front": "What is the primary benefit of using TypeScript with React in large-scale applications?",
      "back": "It provides static type checking, which catches bugs at compile-time rather than runtime, improves developer experience through better IDE autocompletion, and makes refactoring safer and more predictable.",
      "requirement_ids": ["r1"]
    },
    {
      "front": "How do you ensure a React component is accessible for screen reader users?",
      "back": "Use semantic HTML elements (nav, main, button) instead of divs, manage focus states correctly, provide descriptive alt text for images, and ensure sufficient color contrast ratios as defined by WCAG guidelines.",
      "requirement_ids": ["r2"]
    },
    {
      "front": "What is the purpose of an ARIA label in a React component?",
      "back": "It provides an accessible name for an element when the visible text is insufficient or missing, allowing screen readers to announce the element's purpose to users with visual impairments.",
      "requirement_ids": ["r2"]
    },
    {
      "front": "What is the main advantage of using a design system in a React project?",
      "back": "It ensures visual and functional consistency across the application, reduces development time by reusing pre-built components, and establishes a single source of truth for design tokens like colors and spacing.",
      "requirement_ids": ["r3"]
    },
    {
      "front": "How do you handle component variations (e.g., primary vs. secondary buttons) in a design system?",
      "back": "Use props to control variants, sizes, and states. Implement a clear API that maps these props to specific CSS classes or style objects, ensuring the component remains flexible yet constrained by the design system's rules.",
      "requirement_ids": ["r3"]
    },
    {
      "front": "How do you effectively collaborate with a designer when implementing a new UI feature?",
      "back": "Involve them early to discuss technical constraints, ask for clarification on edge cases (like empty states or error handling), and use tools like Figma to inspect spacing, typography, and asset requirements before coding.",
      "requirement_ids": ["r4"]
    },
    {
      "front": "What is the difference between Server Components and Client Components in Next.js?",
      "back": "Server Components render on the server, reducing the JavaScript bundle sent to the client. Client Components are rendered on the client and are necessary for interactivity, state management, and browser-only APIs.",
      "requirement_ids": ["r5"]
    },
    {
      "front": "When should you use 'use client' in a Next.js application?",
      "back": "Use it when a component requires React hooks (like useState or useEffect), event listeners (like onClick), or browser-specific APIs, as these features require the client-side environment.",
      "requirement_ids": ["r5"]
    },
    {
      "front": "What is the core philosophy of React Testing Library?",
      "back": "Test components the way a user interacts with them. Focus on testing the rendered output and user behavior rather than internal implementation details like state or method calls.",
      "requirement_ids": ["r6"]
    },
    {
      "front": "What is the primary use case for Playwright in a React project?",
      "back": "End-to-end (E2E) testing. It simulates real user interactions across multiple browsers to verify that critical user flows (like authentication or checkout) work as expected in a production-like environment.",
      "requirement_ids": ["r6"]
    },
    {
      "front": "How do you manage TypeScript 'any' types in a production codebase?",
      "back": "Avoid 'any' whenever possible. Use 'unknown' for values with unknown types, define explicit interfaces or types for props and state, and use type guards to narrow types safely.",
      "requirement_ids": ["r1"]
    },
    {
      "front": "How do you resolve a conflict between a designer's request and technical feasibility?",
      "back": "Communicate the technical trade-offs (e.g., performance impact or development time) clearly. Propose alternative solutions that achieve the same design goal while maintaining performance and accessibility standards.",
      "requirement_ids": ["r4"]
    }
  ]
}
